  KEY `tafzili_id` (`tafsili_id`),
  CONSTRAINT `hesabha_ibfk_1` FOREIGN KEY (`kol_id`) REFERENCES `hesabha` (`id`),
  CONSTRAINT `hesabha_ibfk_2` FOREIGN KEY (`moein_id`) REFERENCES `hesabha` (`id`),
